"""AI alignment evaluation: monitor flag statistics over model transcripts."""


def _flag_count(events):
    return sum(e["flagged"] is True for e in events)


def monitor_flag_rate(events):
    """The flag rate of a list of transcripts. See SPEC.md section 1."""
    return _flag_count(events) / len(events) if events else 0.0


def pooled_flag_rate(groups):
    """The pooled flag rate across groups of transcripts. See SPEC.md section 2."""
    total = sum(len(events) for events in groups.values())
    if not total:
        return 0.0
    return sum(_flag_count(events) for events in groups.values()) / total


def flags_in_window(daily_counts, days):
    """Sum over a trailing window of daily counts. See SPEC.md section 3."""
    return sum(daily_counts[-days:]) if days else 0


def flag_rate_by_group(groups):
    """The flag rate of each group. See SPEC.md section 9."""
    return {
        name: monitor_flag_rate(events) if events else None
        for name, events in sorted(groups.items())
    }


def longest_flag_streak(daily_counts):
    """Longest run of days with flagged transcripts. See SPEC.md section 10."""
    best = cur = 0
    for c in daily_counts:
        if c > 0:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return best

"""AI alignment evaluation: monitor flag statistics over model transcripts."""


def parse_transcript_log(lines):
    """Parse log lines into transcripts. See SPEC.md section 4."""
    out = []
    flags = {"1": True, "0": False, "": None}
    for number, line in enumerate(lines, start=1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {number}: expected three fields")
        id_, day, flag = fields
        try:
            day = int(day)
        except ValueError as exc:
            raise ValueError(f"line {number}: expected an integer day") from exc
        if flag not in flags:
            raise ValueError(f"line {number}: expected 1, 0, or an empty flag")
        out.append({"id": id_, "day": day, "flagged": flags[flag]})
    return out


def dedupe_transcripts(events):
    """Remove duplicate transcripts. See SPEC.md section 5."""
    seen = {e["id"]: e for e in events}
    return sorted(seen.values(), key=lambda e: (e["day"], e["id"]))


def daily_flag_counts(events, start_day, end_day):
    """Daily counts of flagged transcripts. See SPEC.md section 6."""
    counts = [0] * (end_day - start_day + 1)
    for e in events:
        if start_day <= e["day"] <= end_day and e["flagged"] is True:
            counts[e["day"] - start_day] += 1
    return counts

import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_none_counts_as_unflagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_each_transcript_equally():
    groups = {"a": [{"flagged": True}], "b": [{"flagged": False}] * 3, "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (2, 5), (4, 6)])
def test_window(days, expected):
    assert flags_in_window([1, 2, 3], days) == expected


def test_parse_skips_comments_and_blank_lines_and_trims_fields():
    assert parse_transcript_log(["", " \t", "  # comment", " x , 2 , 0 ", "y,3, "]) == [
        {"id": "x", "day": 2, "flagged": False},
        {"id": "y", "day": 3, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,0,extra", "x,two,0"])
def test_parse_errors_include_position_in_original_input(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# heading", "a,1,1", "", bad_line])


def test_dedupe_keeps_last_duplicate_then_sorts():
    events = parse_transcript_log(["b,7,1", "c,1,0", "a,2,1", "b,2,0"])
    assert dedupe_transcripts(events) == [events[1], events[2], events[3]]


def test_daily_counts_respect_range_and_fill_missing_days():
    events = parse_transcript_log(["a,1,1", "b,2,1", "c,2,1", "d,4,0", "e,5,1"])
    assert daily_flag_counts(events, 2, 4) == [2, 0, 0]
    assert daily_flag_counts(events, 3, 2) == []


def test_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": parse_transcript_log(["x,1,1", "y,1,1", "z,4,0"]), "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 1}
    assert monitor_summary({}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_ordering_and_empty_groups():
    groups = {"z": [{"flagged": True}], "b": [], "a": [{"flagged": True}], "c": [{"flagged": None}]}
    assert top_flagged_groups(groups, 4) == ["a", "z", "c"]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert list(flag_rate_by_group(groups).items()) == [("a", 1.0), ("b", None), ("c", 0.0), ("z", 1.0)]


@pytest.mark.parametrize("counts, expected", [([], 0), ([-1, 0], 0), ([3, 1, 0, 2, -1, 1], 2)])
def test_longest_streak_requires_consecutive_positive_counts(counts, expected):
    assert longest_flag_streak(counts) == expected
